   },
   "condition": {
    "in": [
     {
      "var": "contract.termination_type"
     },
     [
      "EARLY"
     ]
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": {
      "var": "contract.base_rate"
    },
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-P086-S2-R13-02",
   "status": "OK",
   "label": "중도해지금리 계산",
   "source": {
    "quote": "3개월 이상 | 기본금리 x 50% x 경과월수/계약월수(단, 최저금리는 0.1)"
   },
   "let": {
    "contract_term_months": {
      "var": "contract.term_months"
    },
    "elapsed_months": {
      "count_distinct_months": {
        "event": "DEPOSIT",
        "within": {
          "month_range": {
            "from": {
              "anchor": "contract.start_date",
              "offset_months": 1,
