   "status": "OK",
   "label": "자동이체 우대이율 적용",
   "source": {
    "quote": "▪ 자동이체 우대이율: 연 0.1%p"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "count_distinct_months": {
         "event": "DEPOSIT",
         "within": {
          "ref": "$window"
         }
        }
       },
       2
      ]
     },
     {
      ">=": [
       {
        "count_distinct_months": {
         "event": "DEPOSIT",
         "within": {
          "ref": "$window"
         },
         "where": {
          "var": "deposit.channel",
          "in": [
           "ONLINE",
           "INTERNET",
           "MOBILE",
           "ATM"
          ]
         }
        }
       },
       2
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  }
 ]
}

